// hooks/useSteamSearch.ts
'use client';
import { useState } from 'react';

export function useSteamSearch() {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const searchProfile = async (input: string): Promise<string> => {
    setIsLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/steam/resolve?input=${encodeURIComponent(input)}`);
      
      if (!response.ok) {
        const errorData = await response.json();
        // Convertimos cualquier error a string
        throw new Error(errorData.message || 'Error al buscar el perfil');
      }

      const data = await response.json();
      return data.steamId;
    } catch (err) {
      // Aseguramos que el error siempre sea un string
      const errorMessage = err instanceof Error 
        ? err.message 
        : 'Error desconocido al buscar el perfil';
      
      setError(errorMessage);
      throw errorMessage; // Lanzamos un string en lugar de un objeto Error
    } finally {
      setIsLoading(false);
    }
  };

  return { searchProfile, isLoading, error };
}
